import functools
import inspect
from typing import ForwardRef, Any
from fastapi.dependencies.utils import get_typed_signature

class A:
    pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def my_func(x: "A"):
    return x

wrapped_func = wrapper(my_func)

def test_wrapped_forward_ref():
    try:
        sig = get_typed_signature(wrapped_func)
        print("Successfully got signature")
        for param in sig.parameters.values():
            print(f"Param {param.name}: {param.annotation}")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
        raise e
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_forward_ref()
