import functools
import inspect
from typing import ForwardRef, Any, Dict
from fastapi.dependencies.utils import get_typed_signature

class B:
    pass

class A:
    def method(self, x: "B") -> "B":
        return x

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

# Wrap the method
# A().method is a bound method.
# functools.wraps(A().method) will copy __annotations__ from A.method
wrapped_method = wrapper(A().method)

print(f"Wrapped method globals: {wrapped_method.__globals__ is wrapper.__globals__}")
print(f"Original method globals: {A.method.__globals__ is A.__globals__}")

try:
    sig = get_typed_signature(wrapped_method)
    print("Success!")
    print(sig)
except NameError as e:
    print(f"Caught expected NameError: {e}")
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")
    import traceback
    traceback.print_exc()

