    d1 = Depends(lambda: None)
    d2 = Depends(lambda: None) # This will be a different lambda

    # We need to use the same dependency to test equality and hash
    dep = lambda: None
    d1 = Depends(dep)
    d2 = Depends(dep)

    print(f"d1: {d1}")
    print(f"d2: {d2}")
    print(f"d1 == d2: {d1 == d2}")
    try:
        print(f"hash(d1): {hash(d1)}")
        print("Depends is hashable")
    except TypeError as e:
        print(f"Depends is NOT hashable: {e}")

    s1 = Security(dep, scopes=["admin"])
    s2 = Security(dep, scopes=["admin"])

    print(f"s1: {s1}")
    print(f"s2: {s2}")
    print(f"s1 == s2: {s1 == s2}")
    try:
        print(f"hash(s1): {hash(s1)}")
        print("Security is hashable")
    except TypeError as e:
        print(f"Security is NOT hashable: {e}")

