    try:
        s = {d1, d2}
        print(f"Set of Depends size: {len(s)}")
    except TypeError as e:
        print(f"Cannot put Depends in a set: {e}")

    try:
        s = {s1, s2}
        print(f"Set of Security size: {len(s)}")
    except TypeError as e:
        print(f"Cannot put Security in a set: {e}")

if __name__ == "__main__":
