import re
from typing import Iterable, NamedTuple, Optional

class _AnsiToken(NamedTuple):
    plain: str = ""
    sgr: Optional[str] = ""
    osc: Optional[str] = ""

def _ansi_tokenize(ansi_text: str, re_ansi) -> Iterable[_AnsiToken]:
    position = 0
    for match in re_ansi.finditer(ansi_text):
        start, end = match.span(0)
        osc, sgr = match.groups()
        if start > position:
            yield _AnsiToken(ansi_text[position:start])
        if sgr:
            if sgr == "(":
                position = end + 1
                continue
            if sgr.endswith("m"):
                yield _AnsiToken("", sgr[1:-1], osc)
        else:
            yield _AnsiToken("", sgr, osc)
        position = end
    if position < len(ansi_text):
        yield _AnsiToken(ansi_text[position:])

# Current regex
re_ansi_current = re.compile(
    r"""
(?:\\x1b\\](.*?)\\x1b\\\\)|\n(?:\\x1b([(@-Z\\\\-_]|\\[[0-?]*[ -/]*[@-~]))\n""",
    re.VERBOSE,
)

# Proposed regex
re_ansi_proposed = re.compile(
    r"""
(?:\\x1b\\](.*?)\\x1b\\\\)|\n(?:\\x1b([0-Z\\\\-_]|\\[[0-?]*[ -/]*[@-~]))\n""",
    re.VERBOSE,
)

test_text = "Hello \x1b0 World \x1b7 Test \x1b[0m Reset"

print("Current:")
for token in _ansi_tokenize(test_text, re_ansi_current):
    print(token)

print("\nProposed:")
for token in _ansi_tokenize(test_text, re_ansi_proposed):
    print(token)

