from fastapi import FastAPI, APIRouter, FastAPIError
import pytest

def test_include_router_into_itself():
    app = FastAPI()
    router = APIRouter()
    try:
        router.include_router(router)
    except FastAPIError as e:
        print(f"Caught expected error: {e}")
        return
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        return
    print("No error raised when including router into itself!")

if __name__ == "__main__":
    test_include_router_into_itself()

