from fastapi import FastAPI, Depends, Security
from fastapi.security import OAuth2PasswordBearer
from fastapi.testclient import TestClient
import json

app = FastAPI()

auth_read = OAuth2PasswordBearer(tokenUrl="token", scopes={"read": "Read"})
auth_write = OAuth2PasswordBearer(tokenUrl="token", scopes={"write": "Write"})

@app.get("/read")
def read(token: str = Depends(auth_read)):
    return {"token": token}

@app.get("/write")
def write(token: str = Depends(auth_write)):
    return {"token": token}

client = TestClient(app)

def test_openapi_scopes():
    response = client.get("/openapi.json")
    assert response.status_code == 200
    openapi = response.json()

    security_schemes = openapi["components"]["securitySchemes"]
    assert "OAuth2PasswordBearer" in security_schemes

    scopes = security_schemes["OAuth2PasswordBearer"]["flows"]["password"]["scopes"]
    print(f"Scopes: {scopes}")
    assert "read" in scopes
    assert "write" in scopes

if __name__ == "__main__":
    try:
        test_openapi_scopes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

