from rich.repr import auto
import inspect

class BadEq:
    def __eq__(self, other):
        return True
    def __repr__(self):
        return "BadEq()"

@auto
class Foo:
    def __init__(self, x=BadEq()):
        self.x = x

foo = Foo()
r = repr(foo)
print(f"Repr: {r}")
if r == "Foo(BadEq())":
    print("BUG DETECTED: Default value was included in repr because it was mistaken for inspect.Parameter.empty")
elif r == "Foo()":
    print("BUG NOT DETECTED: Default value was correctly omitted")
else:
    print(f"Unexpected repr: {r}")

