from fastapi.sse import ServerSentEvent
from pydantic import ValidationError
import pytest

def test_sse_event_no_newlines():
    try:
        ServerSentEvent(event="greeting\n")
    except ValidationError as e:
        assert "SSE field must not contain newlines" in str(e)
    else:
        pytest.fail("Should have raised ValidationError for newline in event")

def test_sse_id_no_newlines():
    try:
        ServerSentEvent(id="123\r\n")
    except ValidationError as e:
        assert "SSE field must not contain newlines" in str(e)
    else:
        pytest.fail("Should have raised ValidationError for newline in id")

def test_sse_event_ok():
    event = ServerSentEvent(event="greeting")
    assert event.event == "greeting"

def test_sse_id_ok():
    event = ServerSentEvent(id="123")
    assert event.id == "123"

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

